INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist jedes Dienst-Protokoll auf Schicht 7 beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Manche arbeiten auf tieferen Schichten"}, {"text": "Ja", "correct": false, "because": "Z. B. DHCP auf Schicht 2/3"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutze ich für Webseiten?', 3, '[{"text": "HTTP", "correct": true, "because": "Standard für Webzugriff"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}, {"text": "SMTP", "correct": false, "because": "E-Mail-Versand"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sind typisch für Netzwerkdienste?', 5, '[{"text": "DNS", "correct": true, "because": "Namensauflösung"}, {"text": "DHCP", "correct": true, "because": "IP-Vergabe"}, {"text": "ICMP", "correct": false, "because": "Diagnose, kein Dienst"}, {"text": "ARP", "correct": false, "because": "Adresszuordnung, kein Dienst"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) FTP überträgt Dateien. b) Es verschlüsselt Daten automatisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung braucht SFTP"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Dienst-Protokolls?', 4, '[{"text": "Portnummer", "correct": false, "because": "Definiert Dienst"}, {"text": "Sicherheitsanforderung", "correct": false, "because": "Schutz wichtig"}, {"text": "Router-Design", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DNS nur Namen auflöst?', 2, '[{"text": "Ja", "correct": true, "because": "Primäre Funktion"}, {"text": "Nein", "correct": false, "because": "Hauptzweck ist Auflösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll ist für E-Mail-Versand zuständig?', 3, '[{"text": "SMTP", "correct": true, "because": "Sendet E-Mails"}, {"text": "IMAP", "correct": false, "because": "Empfang und Verwaltung"}, {"text": "HTTP", "correct": false, "because": "Webzugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben Dienst-Protokolle?', 5, '[{"text": "Spezifische Ports", "correct": true, "because": "Identifizieren Dienste"}, {"text": "Client-Server-Modell", "correct": true, "because": "Grundprinzip"}, {"text": "Physische Kabel", "correct": false, "because": "Hardware-Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) HTTP ist unsicher. b) Es braucht immer SSL. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSL ist optional (HTTPS)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Dienst-Protokolle?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Portzuweisung", "correct": false, "because": "Definiert Dienst"}, {"text": "Monitorauflösung", "correct": true, "because": "Kein Netzwerkbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist DHCP ein Dienst-Protokoll?', 2, '[{"text": "Ja", "correct": true, "because": "Vergibt IPs dynamisch"}, {"text": "Nein", "correct": false, "because": "Es ist ein Dienst"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle sichern Datenübertragung?', 4, '[{"text": "HTTPS", "correct": true, "because": "Verschlüsselt Web"}, {"text": "SFTP", "correct": true, "because": "Sicherer Dateitransfer"}, {"text": "FTP", "correct": false, "because": "Unverschlüsselt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SMTP auch E-Mails empfängt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Empfang ist IMAP/POP3"}, {"text": "Ja", "correct": false, "because": "Nur Versand"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Dienst-Protokoll?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schutz der Daten"}, {"text": "Maximale Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Einfache Installation", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DNS läuft auf Port 53. b) Es verschlüsselt Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste nutzen diese Protokolle?', 5, '[{"text": "HTTP für Web", "correct": true, "because": "Webseitenübertragung"}, {"text": "IMAP für E-Mail", "correct": true, "because": "E-Mail-Verwaltung"}, {"text": "TCP für Dateien", "correct": false, "because": "Transportprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Dienst-Protokollen unwichtig?', 3, '[{"text": "Portnummer", "correct": false, "because": "Identifiziert Dienst"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Funktion"}, {"text": "Gehäusefarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft HTTPS auf Port 80?', 3, '[{"text": "Nein", "correct": true, "because": "Port 443 für HTTPS"}, {"text": "Ja", "correct": false, "because": "Port 80 ist HTTP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob FTP sicher ist?', 2, '[{"text": "Nein", "correct": true, "because": "Keine Verschlüsselung"}, {"text": "Ja", "correct": false, "because": "SFTP ist sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wähle ich für dynamische IPs?', 4, '[{"text": "DHCP", "correct": true, "because": "Automatische Vergabe"}, {"text": "DNS", "correct": false, "because": "Namensauflösung"}, {"text": "SMTP", "correct": false, "because": "E-Mail-Versand"}]');
